import pytest


class DivZero(Exception):
    """Raised when dividing by zero. Carries the numerator."""

    a: int

    def __init__(self, a: int) -> None:
        self.a = a


def safe_div(a: int, b: int) -> int:
    """Return a // b (floor division). Raise DivZero(a) when b == 0."""
    if b == 0:
        raise DivZero(a)
    return a // b


def test_safe_div_basic() -> None:
    assert safe_div(7, 2) == 3


def test_safe_div_exact() -> None:
    assert safe_div(6, 3) == 2


def test_safe_div_zero_numerator() -> None:
    assert safe_div(0, 5) == 0


def test_safe_div_negative_numerator_floors() -> None:
    assert safe_div(-7, 2) == -4


def test_safe_div_by_zero_raises_with_numerator() -> None:
    with pytest.raises(DivZero) as info:
        safe_div(9, 0)
    assert info.value.a == 9
